#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=47 --disabled '--description=Old test rule'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=47 --disabled '--description=Old test rule'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Reject the rest from LAN'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=Reject the rest from LAN'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   Block countries: references 'Blocked countries': country group; the source 'Blocked countries' holds members only its platform knows; a rule of Google Cloud names addresses
#   LAN to Internet web: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   LAN web again: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   Admins to DMZ: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   LAN to DMZ web not mail: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   LAN SSH out: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone OT, and a rule of Google Cloud names no zone: give the networks behind OT with --zone-network
#   LAN SSH out-2: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone DMZ, OT, and a rule of Google Cloud names no zone: give the networks behind DMZ, OT with --zone-network
#   Internet to web: the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   Internet to mail: the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   OT to SCADA: the source of the rule is in zone OT, and a rule of Google Cloud names no zone: give the networks behind OT with --zone-network; the destination of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network
#   DMZ updates: the source of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network; the destination 'update-sites' holds members only its platform knows; a rule of Google Cloud names addresses
#   Finance to app: source user match Finance is not converted; the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zon
#   DNS in office hours: schedule 'Work hours (5 Day week)' is not converted; the rule would apply at all times; the source of the rule is in zone OT, and a rule of Google Cloud names no zone: give the networks behind OT with --zone-network; the destination of the rule is in zone LAN, and a rule of Google Cloud names no zon
#   LAN6 to Internet: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
